const fn = new Function(code + "\nreturn { format };");
const { format } = fn();
if (format("  hi  ") !== "hi") throw new Error("Strings are trimmed.");
if (format(3.14159) !== "3.14") throw new Error("Numbers get two decimals.");
if (format(true) !== "yes" || format(false) !== "no") throw new Error("Booleans map to yes/no.");
if (format(null) !== "—" || format(undefined) !== "—") throw new Error("Nullish becomes a dash.");

const fn = new Function(code + "\nreturn { format };");
const { format } = fn();
if (format(0) !== "0.00") throw new Error("0 must format as a number — beware truthiness checks.");
if (format("") !== "") throw new Error("Empty string is still a string (trimmed).");
